insert into public.programs (id, program, level, state, funds_what, hub_stage, award_range, match_requirement, cycle_deadline, eligibility_notes, url, date_verified, none_found) values
(1, 'Local Food Promotion Program (LFPP), USDA AMS (LAMP)', 'Federal', 'All', 'Planning and implementation for intermediaries: aggregation, processing, distribution, storage, marketing. No land purchase or building construction.', 'Planning; Startup; Scaling', 'Planning $25K–100K; Implementation $100K–500K; Turnkey $50K–100K', '25% of federal request, cash and/or in-kind, committed by selection', 'FY2026 closed Jun 5, 2026 (~$13.84M). FY2027: no round expected until Congress restores LAMP funding; LAMP lost its budget baseline when the farm bill extension lapsed Sep 30, 2026 (per AgSist summary of CRS; confirm with AMS).', 'Ag businesses and co-ops (for-profits appear eligible), nonprofits, food councils, local gov, tribes. Only 11.5% of eligible FY2025 applications were funded.', 'https://www.ams.usda.gov/services/grants/lfpp', '2026-11-22', false),
(2, 'Regional Food System Partnerships (RFSP), USDA AMS (LAMP)', 'Federal', 'All', 'Public-private partnerships to plan and build regional food systems, incl. shared cold storage and institutional market links', 'Planning; Scaling', 'FY2025 awards ranged ~$242K–$959K (7 grants, $4.71M total)', '25% (existing research says cash only; not re-verified)', 'FY2026 round ($4.71M) closed Jun 5, 2026. FY2027 tied to the same LAMP funding lapse.', 'Hub applies as part of a partnership with producers, processors and institutional buyers', 'https://www.ams.usda.gov/sites/default/files/media/FY25_RFSP_DoFP.pdf', '2026-11-22', false),
(3, 'Value-Added Producer Grant (VAPG), USDA RD', 'Federal', 'All', 'Planning (feasibility, business plans) or working capital: processing, packaging, marketing, inventory, salaries', 'Planning; Startup; Scaling', 'Planning up to $50K; Working capital up to $200K', '1:1 (dollar for dollar)', 'FY2026 closed Apr 22, 2026 (~$25M available; $26M+ awarded Sep 18, 2026). FY2027 notice not posted as of Nov 22, 2026; window is usually Jan–May.', 'Producers, producer groups, farmer co-ops and majority producer-controlled businesses only. Most nonprofit or investor-owned hubs do not qualify.', 'https://www.rd.usda.gov/programs-services/business-programs/value-added-producer-grants', '2026-11-22', false),
(4, 'Rural Business Development Grant (RBDG), USDA RD', 'Federal', 'All (rural)', 'Technical assistance, training, feasibility studies, business plans, incubators, equipment and revolving loan funds benefiting small rural businesses', 'Planning; Startup', '$10K–500K typical (FY2026 total $27.7M)', 'None', 'FY2026 closed Jun 30, 2026 (SECD track Jun 15). FY2027 notice not yet posted.', 'Public bodies, nonprofits and tribes; project must benefit areas outside cities of 50,000+. For-profit hubs cannot apply directly.', 'https://www.rd.usda.gov/programs-services/rural-business-development-grants', '2026-11-22', false),
(5, 'Business & Industry (B&I) Loan Guarantee, USDA RD', 'Federal', 'All (rural)', 'Real estate, equipment, inventory, working capital, acquisitions. Not lines of credit.', 'Scaling; Mature', 'Loans up to $25M', 'n/a (lender guarantee: 85% on loans up to $5M, 80% from $5M–25M in FY2026)', 'Ongoing through lenders', 'For-profits, co-ops, nonprofits with an operating business, tribes. Rural areas outside towns of 50,000+.', 'https://www.rd.usda.gov/media/file/download/comparison-usda-rd-and-sba-business-loans.pdf', '2026-11-22', false),
(6, 'Community Facilities Direct Loan & Grant, USDA RD', 'Federal', 'All (rural)', 'Buy, build or improve essential community facilities; USDA names food hubs as eligible', 'Scaling; Mature', 'Loans up to 40 years (4.500–4.750%, Apr–Sep 2026); grants up to 75% of project cost for the smallest, lowest-income communities', 'Grant share scales with community size and income', 'Rolling, year-round', 'Public bodies, community-based nonprofits, tribes. Rural population cap not re-verified for this directory.', 'https://www.rd.usda.gov/programs-services/community-facilities/community-facilities-direct-loan-grant-program', '2026-11-22', false),
(7, 'Food Supply Chain Guaranteed Loan, USDA RD', 'Federal', 'All', 'Start-up or expansion of aggregation, processing, storage, transport and distribution', 'Scaling; Mature', 'Guarantees on loans up to $40M', 'n/a (lender guarantee)', 'UNVERIFIED: one-time ARPA money, ''until funds expended''; 38 loans ($379.3M) closed in 2024. Could not confirm funds remain.', 'Borrower must work in the middle of the food supply chain', 'https://fpi.omb.gov/program/10.380.html', '2026-11-22', false),
(8, 'HFFI Food Access & Retail Expansion (FARE) Fund grants, Reinvestment Fund for USDA', 'Federal', 'All', 'Feasibility, market studies, equipment, acquisition, construction, software and other one-time costs; plus third-party TA', 'Planning; Startup; Scaling', 'Grants $20K–250K; TA up to $75K', 'Not stated', '2026: inquiry Jul 31, 2026; invited applications due Oct 30, 2026 (closed). Next round not announced.', 'For-profits, nonprofits, co-ops, governments (grants and TA only). Must serve an eligible underserved area; food hubs supplying SNAP retailers are a named example.', 'https://ruralgrocery.org/summit/agenda/2026-session-slides/Misak_Palombo_HFFI-FARE-Fund.pdf', '2026-11-22', false),
(9, 'HFFI FARE Fund loans, Reinvestment Fund for USDA', 'Federal', 'All', 'Loans for food retail and supply-chain projects in underserved areas', 'Scaling; Mature', '$500K–5M', 'Not stated', 'UNVERIFIED: current loan window not confirmed', 'Governments not eligible for loans', 'https://www.ruralhealthinfo.org/funding/6289', '2026-11-22', false),
(10, 'HFFI Local & Regional Healthy Food Financing Partnerships', 'Federal', 'All', 'Grants to local, state or regional financing partnerships that then lend, grant or credit-enhance food retailers and supply-chain firms', 'All (indirect)', '$200K–3M per partnership ($20M round)', 'Not stated', 'Due Sep 18, 2026 (closed)', 'Hubs do not apply directly; they benefit through a partnership in their region', 'https://www.reinvestment.com/?p=26386', '2026-11-22', false),
(11, 'Patrick Leahy Farm to School Grant, USDA FNS', 'Federal', 'All', 'Farm-to-school projects incl. local procurement; hubs can process and supply schools as partners', 'Startup; Scaling', '$100K–500K', 'UNVERIFIED for FY2026 (check RFA)', 'FY2026 closed Dec 5, 2025 ($18M). FY2027 RFA not posted as of Nov 22, 2026.', 'Applicants must apply with partners; school districts, nonprofits, agencies and others', 'https://www.fns.usda.gov/f2s/grant', '2026-11-22', false),
(12, 'Resilient Food Systems Infrastructure (RFSI), USDA AMS via states', 'Federal', 'Varies (state-run)', 'Middle-of-supply-chain equipment and infrastructure', 'Startup; Scaling', 'Varies by state (CA: infrastructure $100K–3M; equipment $10K–100K)', 'Varies by state (CA: 50% infrastructure, 25% small/underserved, none equipment-only)', 'One-time 2023 money; most state rounds closed (CA, NJ). A 2026 Senate bill would make it permanent; not enacted.', 'Reimbursement-based; Fair Food Fund bridge-financed MI grantees while they waited', 'https://www.ams.usda.gov/services/grants/rfsi', '2026-11-22', false),
