(15, 'SBA International Trade Loan ''90% Grocery Guarantee''', 'Federal', 'All', 'Production, processing and distribution capacity', 'Scaling; Mature', 'Loan cap not stated in release', 'n/a (90% guarantee vs. 75% standard 7(a))', 'Eligible from May 1, 2026; no end date stated', 'Eligible NAICS include grocery wholesalers, refrigerated warehousing and specialized freight trucking. Whether a given hub''s NAICS code qualifies needs lender check.', 'https://legacy.sba.gov/article/2026/03/27/sba-announces-grocery-guarantee-promote-affordability', '2026-11-22', false),
(16, 'SBA Microloan', 'Federal', 'All', 'Small working capital, inventory, equipment', 'Startup', 'Up to $50K', 'n/a', 'Ongoing through intermediaries', 'Source is a third-party review (Bankrate); confirm terms with an SBA intermediary', 'https://www.bankrate.com/loans/small-business/reviews/kiva', '2026-11-22', false),
(17, 'New Markets Tax Credit (NMTC), via CDEs', 'Federal', 'All', 'Equity-like gap financing for facilities in low-income census tracts', 'Mature', 'CY2026 round: $5B in allocation authority nationally (to CDEs)', 'n/a (tax credit equity)', 'CDE applications due Nov 10, 2026; hubs approach CDEs that already hold allocations', 'Projects must be in qualifying tracts; minimum deal size not verified here. Food banks have used it for cold storage (Great Plains Food Bank, 2026).', 'https://www.cdfifund.gov/news/738', '2026-11-22', false),
