(411, 'Interest Rate Reduction Program (linked deposit), Texas Agricultural Finance Authority (TDA)', 'State', 'TX', 'Lower interest rates on loans to create or expand agricultural businesses via state deposits with the lender', 'Startup; Scaling; Mature', 'Loans up to $500K (IRR) or $1M (FIRR) per borrower', 'None stated; no program fees', 'Open year-round, subject to funding', 'Any person or Texas agricultural business; funds may go to ''any enterprise based on agriculture''. Lender must be a Comptroller-approved state depository. Can be stacked with the loan guarantee.', 'https://texasagriculture.gov/GrantsServices/RuralEconomicDevelopment/TexasAgriculturalFinanceAuthority/InterestRateReduction.aspx', '2026-11-22', false),
(412, 'PeopleFund small business loans (Texas CDFI)', 'Private', 'TX', 'Equipment, working capital term loans, lines of credit, real estate; SBA 504', 'Startup; Scaling; Mature', 'Not stated for direct loans; up to $5M through SBA', 'Not stated', 'Open, rolling', 'Statewide CDFI lending to small businesses, start-ups and nonprofits, focus on low and moderate income areas. No food or ag-specific product found; general small business fit. Was a TDA Capital for Texas (SSBCI) partner in 2016 with LiftFund and BCL of Texas.', 'https://peoplefund.org/loans/', '2026-11-22', false),
(413, 'Utah Food Security Grant (UFSG), Utah Department of Agriculture and Food', 'State', 'UT', 'Food supply chain projects from production through processing, distribution and local food promotion', 'Startup; Scaling; Mature', 'Microgrant $1K–10K; Startup $10K–50K; Standard $10K–1M (about $9.27M total in 2026)', 'None stated in RFA', '2026 window July 21 to Aug 31, 2026 (closed); Year 1 of a 5-year initiative, so further cycles expected; funds spent by Sept 30, 2027', '2026 cycle funded by CMS Rural Health Transformation Program via Utah DHHS; earlier cycles over past four years. For-profits, nonprofits, co-ops eligible; distributors named; 51% Utah-grown and 25% rural distribution rules', 'https://ag.utah.gov/wp-content/uploads/FINAL-2026-UFSG-RFA.pdf', '2026-11-22', false),
(414, 'Local Food Purchase Assistance (state-funded continuation), Utah Legislature via Department of Health and Human Services', 'State', 'UT', 'State purchase of local food from producers for food banks and food programs', 'Scaling; Mature', 'About $630K appropriated 2026 (per UPR); $3M FY2027 request', 'Not applicable', '2026 appropriation continues program after federal LFPA ended; FY2027 funding status UNVERIFIED', 'Recipients are government or nonprofit entities (e.g., food banks); hubs participate as suppliers/partners. $630K figure from news report, not budget document', 'https://www.upr.org/utah-news/2026-03-12/federal-cuts-threaten-a-lifeline-program-for-small-utah-farmers', '2026-11-22', false),
