(452, 'Food Security and Wisconsin Products Program, DATCP', 'State', 'WI', 'Purchase of Wisconsin-sourced food (100% of budget) for free distribution through food assistance networks', 'Scaling; Mature', 'Not stated ($5M awarded competitively; $10M in 2025-27 budget)', 'None', 'Closed; last deadline Oct 1, 2026; projects start Dec 2026; state-funded biennially', 'Applicants are nonprofit food assistance organizations; hubs benefit as Wisconsin suppliers or partners (projects must collaborate). Functions as Wisconsin''s state-funded successor to LFPA.', 'https://datcp.wi.gov/Pages/AgDevelopment/FoodSecurityInitiative.aspx', '2026-11-22', false),
(453, 'Resilient Food Systems Infrastructure (RFSI) Program, DATCP (USDA pass-through)', 'State', 'WI', 'Middle-of-supply-chain equipment and infrastructure', 'Startup; Scaling; Mature', 'Not stated ($27.2M across 51 equipment and 30 infrastructure grants)', 'Not stated', 'One-time; awards Jan 6, 2025 ($23.2M) and equipment-only round announced Oct 24, 2025; no further round listed', 'Largest RFSI program in this region; subaward list PDF on page names recipients.', 'https://datcp.wi.gov/pages/agdevelopment/rfsi.aspx', '2026-11-22', false),
(454, 'Specialty Crop Block Grant, DATCP', 'State', 'WI', 'Projects benefiting the specialty crop industry as a whole', 'Startup; Scaling; Mature', 'Not stated on page (see 2026 RFP)', 'Not stated', 'Closed; last deadline Mar 3, 2026; recurring annually, next RFP expected winter 2026-27', 'Nonprofits, producer organizations, government, universities, other ag groups; cannot directly profit a single organization, so hubs need broad-benefit projects.', 'https://datcp.wi.gov/Pages/AgDevelopment/SpecialtyCropBlockGrants.aspx', '2026-11-22', false),
(455, 'None found: state healthy food financing initiative (Wisconsin)', 'State', 'WI', 'Category checked: Healthy food financing', 'N/A', 'N/A', 'N/A', 'Checked 2026-11-22', 'Healthy Food Access Portal lists only the Milwaukee Fresh Food Access Fund (city program, 1:1 matching grants), not a state program.', 'http://healthyfoodaccess.org/view-hffi-efforts-by-state/midwest/', '2026-11-22', true),
(456, 'None found (current): Wisconsin Farm to School Grant Pilot, DATCP (ended)', 'State', 'WI', 'Category checked: Farm to school / institution', 'N/A', '$10K–40K (past pilot, $250K total)', 'Not stated', 'Checked 2026-11-22; listed by DATCP as previously active, one-time USDA-funded pilot, no current round', 'No active state farm to school grant found.', 'https://datcp.wi.gov/Pages/AgDevelopment/FarmToSchool.aspx', '2026-11-22', true),
(457, 'Small Business Development Grant (SBDG), Wisconsin Economic Development Corp. (WEDC)', 'State', 'WI', 'Grants to EDOs, municipalities, counties and Tribes to run small business matching grant or financing programs (firms under 25 FTEs)', 'Startup; Scaling', '$50K–250K to the intermediary ($1.5M FY2027)', 'None required (scoring bonus)', 'FY27 deadline Oct 2 (2026 per page metadata); likely annual', 'Hubs cannot apply directly; they access funds through a local EDO or community program. Rural and distressed areas prioritized.', 'https://wedc.org/programs/small-business-development-grant/', '2026-11-22', false),
(458, 'Entrepreneur Fund (EFund), CDFI', 'Private', 'WI', 'Working capital, equipment, term and real estate loans to food retailers and producers', 'Startup; Scaling; Mature', 'Not stated', 'Not stated', 'Rolling', 'Serves northern Minnesota and Wisconsin; local food systems lending focus.', 'https://www.efund.org/blog/fueling-vibrant-resilient-communities-through-local-food-systems', '2026-11-22', false),
(459, 'IFF (Midwest nonprofit CDFI, Wisconsin office)', 'Private', 'WI', 'Facility, equipment, vehicle, bridge and flex loans; food desert grocery financing', 'Startup; Scaling; Mature', '$10K–6.5M+', 'As little as 5%', 'Rolling', 'Nonprofit-focused; nonprofit hubs fit best.', 'https://iff.org/services/capital-solutions/', '2026-11-22', false),
(460, 'None found: state-funded WVDA grant for food hubs, aggregation, processing or cold storage', 'State', 'WV', 'Category checked: State ag agency grants', 'N/A', 'N/A', 'N/A', 'Checked 2026-11-22', 'WVDA grants found are federal pass-throughs (RFSI, SCBG). WV Code 19-38 creates a WVDA Agriculture Investment Fund (grants or loans for value-added ag enterprises), but no appropriations, solicitations or awards were found; treat as dormant until confirmed with WVDA.', 'https://code.wvlegislature.gov/pdf/19-38/', '2026-11-22', true),
(461, 'Resilient Food Systems Infrastructure (RFSI) Program, WV Dept. of Agriculture', 'State', 'WV', 'Middle-of-supply-chain processing, aggregation and distribution: infrastructure and equipment grants', 'Startup; Scaling; Mature', 'Not stated in text ($3,340,273 total to 11 projects)', 'Not stated', 'One-time: awards announced May 1, 2025 (5 infrastructure, 6 equipment); no new round announced', 'Recipient list is in an image not readable; hub recipients UNVERIFIED. WVDA also planned supply chain coordination and technical assistance.', 'https://agriculture.wv.gov/?p=15613', '2026-11-22', false),
(462, 'WV Specialty Crop Block Grant Program, WV Dept. of Agriculture', 'State', 'WV', 'Projects that enhance competitiveness of specialty crops (marketing, food safety, distribution)', 'Planning; Startup; Scaling', 'Not stated (about $302K total awarded statewide FY2025)', 'Not stated', 'Closed: 2026 applications due January 30, 2026 (RFA released Dec 19, 2025); recurring annually, next RFA expected about December 2026', 'Small statewide pool. Eligibility details in WVDA application materials (not opened). Added because no WV SCBG row existed.', 'https://agriculture.wv.gov/wvda-announces-request-for-applications-for-2026-specialty-crop-block-grant-program/', '2026-11-22', false),
(463, 'None found: West Virginia state healthy food financing initiative', 'State', 'WV', 'Category checked: Healthy food financing', 'N/A', 'N/A', 'N/A', 'Checked 2026-11-22', 'Search found only federal USDA healthy food awards and bills introduced (2020, 2021) without evidence of an enacted, funded state program.', 'https://www.wvlegislature.gov/Bill_Text_HTML/2021_SESSIONS/RS/bills/HB2050 INTR.pdf', '2026-11-22', true),
(464, 'None found: state-funded WV farm to school grant (WVDA Farm to School is technical support only)', 'State', 'WV', 'Category checked: Farm to school / institution', 'N/A', 'N/A', 'N/A', 'Checked 2026-11-22', 'WVDA Business Development Division supports local purchasing; purchasing is decided by county school systems (about $100M in food per year statewide). No state-level grant found. Hubs sell directly to counties.', 'https://agriculture.wv.gov/ag-business/farm-to-school/', '2026-11-22', true),
(465, 'West Virginia Economic Development Authority (WVEDA) direct loans and industrial development bonds', 'State', 'WV', 'Machinery, equipment and facility financing for businesses', 'Scaling; Mature', 'Not stated', 'Not stated', 'Rolling', 'Self-supporting public corporation; financed equipment for Hernshaw Farms (mushroom grower) per April 2026 WVEDA story. Food/ag eligibility criteria not published on page opened.', 'https://eda.wv.gov/the-wveda-helps-hernshaw-farms-expand-its-operations/', '2026-11-22', false),
(466, 'West Virginia First Small Business Growth Program (SB-1), WV Dept. of Commerce', 'State', 'WV', 'Growth capital (debt or equity) through state-certified growth funds for scaling, expansion or bridging cash flow', 'Scaling; Mature', 'No minimum; up to the greater of 20% of a fund''s authority or $7.5M per business ($100M program)', 'Not stated', 'Growth-fund application window closed May 26, 2026; businesses seek capital from approved funds (ongoing)', 'WV-based businesses under 250 employees; no industry carve-outs, so for-profit hubs qualify. Investor capital, not a grant.', 'https://westvirginia.gov/the-west-virginia-first-small-business-growth-program-sb-1/', '2026-11-22', false),
(467, 'Rural Rehabilitation Loan Fund, WV Dept. of Agriculture', 'State', 'WV', 'Low-interest loans for equipment, buildings and property for emerging and expanding agribusinesses', 'Startup; Scaling', 'Not stated', 'Not stated (collateral required)', 'Rolling', 'Open to agribusinesses, not just farmers; past uses include food manufacturing equipment and buildings for multiple family farms. Business plan required; WVDA staff assist. Rates and terms not posted.', 'https://agriculture.wv.gov/divisions/executive/rural-rehabilitation-loan-fund/', '2026-11-22', false),
(468, 'The Progress Fund small business loans (CDFI)', 'Private', 'WV', 'Loans to new or expanding small businesses incl. local foods makers and local agriculture', 'Startup; Scaling', '$5K to over $1M (page also states $20K minimum; confirm)', 'Not stated', 'Rolling', 'Lends in PA, WV and MD. No dedicated hub product stated on page.', 'https://www.progressfund.org/about-us/', '2026-11-22', false),
(469, 'Value-Added Ag Loan (Grown in Wyoming), Wyoming Business Council', 'State', 'WY', 'Machinery, equipment and facilities for processing or packaging agricultural commodities (no working capital, production costs or refinancing)', 'Startup; Scaling; Mature', 'Not stated', 'Not stated', 'Open: online application via lender; no deadline stated', 'Bank applies; beneficiary is a Wyoming producer, producer group, co-op or agribusiness whose project benefits Wyoming agriculture. Processor or aggregator hubs plausibly fit as agribusinesses. Wyoming Department of Agriculture grant pages returned a bot check and could not be reviewed, so other WDA grants are UNVERIFIED.', 'https://wyomingbusiness.org/business/financing/loans/value-added-ag-loan/', '2026-11-22', false),
(470, 'LFPA Plus, Wyoming Department of Family Services and Food Bank of Wyoming', 'State', 'WY', 'Purchases of local food (including meat from local processors) for food bank distribution, leveraging food hubs', 'Startup; Scaling; Mature', 'Not stated', 'None stated', 'Two-year agreement; current status UNVERIFIED (not confirmed active or terminated)', 'Hubs act as vendors, not applicants; project expects to benefit about 25 farmers, producers and food hubs within 400 miles. No state-funded replacement found.', 'https://www.ams.usda.gov/selling-food-to-usda/lfpacap/plus/signed-agreements/wy', '2026-11-22', false),
(471, 'Resilient Food Systems Infrastructure (RFSI) Program, Wyoming Department of Agriculture (one-time, federal)', 'State', 'WY', 'Infrastructure and equipment for aggregation, processing, storage, transport, wholesaling and distribution of local food (meat and poultry excluded)', 'Startup; Scaling; Mature', 'Not stated per award; $2.2M state total ($1.3M+ to 6 infrastructure projects, $400K+ to 11 equipment-only projects)', 'Not stated', 'Closed, one-time: funds fully awarded; sub-award year UNVERIFIED; no new round', 'Funded projects included freeze-dried foods, honey and dairy processing. Listed for context; no open opportunity. Source is USDA AMS state profile.', 'https://ams-prod.azureedge.us/sites/default/files/media/Wyoming_State_Profile.pdf', '2026-11-22', false),
(472, 'Specialty Crop Block Grant Program, Wyoming Department of Agriculture', 'State', 'WY', 'Projects that increase production, marketing and consumption of specialty crops', 'Planning; Startup; Scaling; Mature', 'UNVERIFIED', 'UNVERIFIED', 'Recurring annually: RFA usually opens in January, deadline usually late March; 2027 cycle expected Jan to Mar 2027 (exact dates UNVERIFIED)', 'Award size, match and eligibility could not be confirmed because the WDA page (agriculture.wy.gov/specialty-crop-program) returned a bot check. Source is University of Wyoming Extension directory listing.', 'https://wyoextension.org/specialty-crop/directory/wyoming-department-of-agriculture-specialty-crop-block-grant-program/', '2026-11-22', false),
(473, 'None found: state healthy food financing initiative', 'State', 'WY', 'Category checked: Healthy food financing', 'N/A', 'N/A', 'N/A', 'Checked 2026-11-22', 'Targeted search found no Wyoming state HFFI or grocery financing program; food access funding found was federal or philanthropic.', 'https://www.ams.usda.gov/selling-food-to-usda/lfpacap/plus/signed-agreements/wy', '2026-11-22', true),
(474, 'School Protein Enhancement Project Mini-Grant, Wyoming Department of Education', 'State', 'WY', 'Processing costs for donated Wyoming meat used in school meals (state- or USDA-inspected plants only)', 'Startup; Scaling; Mature', 'Not stated per award; $25K total', 'Dollar-for-dollar district match on processing costs', 'Closed: 2025-26 deadline Oct 31, 2025; recurrence UNVERIFIED', 'Public schools only; processors and aggregators benefit as vendors. WDE also runs a federally funded Farm to School program; Wyoming LFS (over $1M) was terminated by USDA in spring 2025.', 'https://edu.wyoming.gov/sups-memo/09-22-2024-school-protein-enhancement-project-mini-grant-available/', '2026-11-22', false),
(475, 'Business Ready Community (BRC) Grant and Loan Program, Wyoming Business Council', 'State', 'WY', 'Public infrastructure and buildings that support business recruitment or expansion (Business Committed, Community Readiness, Community Project, loans)', 'Startup; Scaling; Mature', 'Up to $5M (Business Committed, Community Readiness, Loan); Community Project $500K–750K', 'Proposed rules: 25% minimum, half may be in-kind (current match not stated)', 'Business Committed: any time. Other categories have set deadlines (e.g., Planning Sep 1, Community Readiness Nov 1); proposed rules may change or remove categories', 'Cities, towns, counties and joint powers boards apply; a hub would be the business partner or tenant. Rules under revision as of 2026.', 'https://wyomingbusiness.org/communities/business-ready-community/planning', '2026-11-22', false),
(476, 'Partnership loan programs (Challenge, Bridge, Guaranteed Loan Participation), Wyoming Business Council', 'State', 'WY', 'State participation in business loans with local lenders or economic development organizations', 'Startup; Scaling; Mature', 'Challenge up to $500K state share; Bridge up to 35% (max $1M); Guaranteed Participation up to 50% (max $2M)', 'Requires local lender or local EDO participation', 'Open, rolling', 'General Wyoming businesses; not food-specific. Guaranteed participation requires an SBA or USDA guaranteed loan.', 'https://wyomingbusiness.org/business/financing/businesses-seeking-finances/', '2026-11-22', false),
(477, 'Wind River Development Fund (Native CDFI)', 'Private', 'WY', 'Capital access and technical assistance for Native businesses, farmers and ranchers on and around the Wind River Reservation', 'Planning; Startup', 'Not stated', 'Not stated', 'Not stated', 'Only CDFI headquartered in Wyoming (per CDFI Coalition). Loan products not described on the page opened (First Nations grantee profile); fit limited to reservation-area enterprises. No statewide food/ag CDFI found.', 'https://www.firstnations.org/grantee-profiles/wind-river-development-fund/', '2026-11-22', false);
